UPDATE product
title = #{title}, subtitle = #{subtitle}, main_image = #{mainImage}, category_id = #{categoryId}, status = 'PENDING', updated_at = #{updatedAt}, updated_by = #{updatedBy}
WHERE product_id = #{productId} AND is_deleted = 0

UPDATE product
SET status = #{status}, updated_at = NOW(), updated_by = #{updatedBy}
WHERE product_id = #{productId} AND is_deleted = 0

UPDATE product
SET is_deleted = 1, status = 'OFF_SHELF', updated_at = NOW(), updated_by = #{updatedBy}
WHERE product_id = #{productId} AND is_deleted = 0

