mapper.select:
SELECT p.product_id, p.seller_id, p.title, p.subtitle, p.main_image, p.category_id, p.status, MIN(s.price) AS price, COALESCE(SUM(s.stock_available), 0) AS stock, p.created_at FROM product p JOIN sku s ON s.product_id = p.product_id WHERE GROUP BY p.product_id, p.seller_id, p.title, p.subtitle, p.main_image, p.category_id, p.status, p.created_at, p.sales_count HAVING SUM(s.stock_available) > 0 ORDER BY
p.created_at DESC price ASC price DESC p.sales_count DESC p.created_at DESC
LIMIT #{offset}, #{size}

SELECT p.product_id, p.seller_id, p.title, p.subtitle, p.main_image, p.category_id, p.status, MIN(s.price) AS price, COALESCE(SUM(s.stock_available), 0) AS stock, p.created_at FROM product p LEFT JOIN sku s ON s.product_id = p.product_id AND s.is_deleted = 0 WHERE p.is_deleted = 0
AND p.status = #{status}
GROUP BY p.product_id, p.seller_id, p.title, p.subtitle, p.main_image, p.category_id, p.status, p.created_at ORDER BY p.created_at DESC LIMIT #{offset}, #{size}

SELECT p.product_id, p.seller_id, p.title, p.subtitle, p.main_image, p.category_id, p.status, MIN(s.price) AS price, COALESCE(SUM(s.stock_available), 0) AS stock, p.created_at FROM product p LEFT JOIN sku s ON s.product_id = p.product_id AND s.is_deleted = 0 WHERE p.seller_id = #{sellerId} AND p.is_deleted = 0
AND p.status = #{status}
GROUP BY p.product_id, p.seller_id, p.title, p.subtitle, p.main_image, p.category_id, p.status, p.created_at ORDER BY p.created_at DESC LIMIT #{offset}, #{size}
